        let bInputs = Inputs.vectors(H.Vector.self, seed: 0x5BAB_9698_C0AF_D04E)
        let cInputs = Inputs.vectors(H.Vector.self, seed: 0x5BAB_9598_C0AF_CE9B)
        let dInputs = Inputs.vectors(H.Vector.self, seed: 0x5BAB_9498_C0AF_CCE8)
        for (a, b, c, d) in mixedQuadruples(
            aInputs,
            bInputs,
            cInputs,
            dInputs,
            seed: 0xDB69_10EC_A6F2_32FB
        ) {
            let (_, portLanes) = withOutputSpan(capacity: 4 * H.laneCount) { output in
                unsafe H.appendInterleaved4(a, b, c, d, toUnchecked: &output)
            }
            let (_, referenceLanes) = withOutputSpan(capacity: 4 * H.laneCount) { output in
                H.appendInterleaved4(a, b, c, d, to: &output)
            }
            mismatches.check(
                portLanes,
                referenceLanes,
                "a: \(describe(a)), b: \(describe(b)), c: \(describe(c)), d: \(describe(d))"
            )
        }
        mismatches.record()
    }
}
